import hashlib


def keystream(key: bytes, n: int) -> bytes:
    out = b""
    counter = 0
    while len(out) < n:
        out += hashlib.sha256(key + counter.to_bytes(4, "big")).digest()
        counter += 1
    return out[:n]


def xor(data: bytes, stream: bytes) -> bytes:
    return bytes(a ^ b for a, b in zip(data, stream))


def wrap(message: bytes, keys: list[bytes]) -> bytes:
    onion = message
    for key in reversed(keys):
        onion = xor(onion, keystream(key, len(onion)))
    return onion


def peel(onion: bytes, key: bytes) -> bytes:
    return xor(onion, keystream(key, len(onion)))


keys = [b"bob-secret", b"chan-secret", b"dina-secret"]
onion = wrap(b"lipa Dina sats 21000", keys)
for key in keys:
    onion = peel(onion, key)
    print("after", key.decode(), "->", onion)
